private val _localAudioOutput = MutableStateFlow(LocalAudioOutput.Phone)
val localAudioOutput: StateFlow<LocalAudioOutput> = _localAudioOutput.asStateFlow()
fun refreshLocalAudioOutput() = updateLocalAudioOutput()

private fun updateLocalAudioOutput() {
    val device = currentMediaOutputDevice()
    _localAudioOutput.value = if (device == null) LocalAudioOutput.Phone else localAudioOutputOf(
        device.type, device.productName?.toString(), Build.MODEL,
        fallbackName = _bluetoothName.value.takeIf { device.type.toAudioOutputCategory() == AudioOutputCategory.Bluetooth }
    )
}

private fun currentMediaOutputDevice(): AudioDeviceInfo? {
    if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.TIRAMISU) {
        runCatching { audioManager.getAudioDevicesForAttributes(MediaAttributes) }.getOrNull()
            ?.firstOrNull()?.let { return it }
    }
    // API 30–32 fallback: the connected sink Android's media routing prefers.
    return audioManager.getDevices(AudioManager.GET_DEVICES_OUTPUTS)
        .filter { it.isSink }
        .minByOrNull { routePriority(it.type.toAudioOutputCategory()) } // Bluetooth 0, Usb 1, Wired 2, Cast(HDMI) 3, Other 4, BuiltIn 5
}
```
